// Store aggregates the persistence repositories. It owns the connection pool
// and exposes the typed queries generated by sqlc. Phase 1 replaces the flat
// user methods with dedicated repositories as the auth schema grows.
type Store struct {
	DB      *pgxpool.Pool
	queries *sqlc.Queries

	// BeforeFamilyRevoke is a nil-by-default test seam. RevokeFamilyIfStolen
	// calls it after revoking the family and before committing, so a test can
	// prove the revocation itself runs under the per-user lock (the hook sees
	// the lock still held). Production leaves it nil.
	BeforeFamilyRevoke func()

	// BeforePinServerHostKey is a nil-by-default test seam invoked before the
	// TOFU pin write; a non-nil error aborts the write, so a test can force it
	// to fail. Production leaves it nil.
	BeforePinServerHostKey func() error

	// BeforeUpdateServerAgentInfo is a nil-by-default test seam invoked before
	// the inventory write; a non-nil error aborts it, so a test can exercise
	// Validate's restore-on-failure path. Production leaves it nil.
	BeforeUpdateServerAgentInfo func() error

	// BeforeCollectionClear is a nil-by-default test seam invoked inside the
	// collection-replace transactions after the parent row lock and before the
	// clear/insert. A test blocks it to hold a replacement open and prove that
	// a concurrent replacement serializes rather than merging. Production
	// leaves it nil.
	BeforeCollectionClear func()

	// BeforeRepoCacheInsert is a nil-by-default test seam invoked inside
	// ReplaceRepoCache after the cache clear and before the inserts. A non-nil
	// error aborts the transaction so a test can prove a failed refresh leaves
	// the previous repository list intact. Production leaves it nil.
	BeforeRepoCacheInsert func() error

	// AfterEnvReadBeforeSecrets is a nil-by-default test seam invoked inside
	// ListEnvConfigByApp between the env-var read and the secret read. A test
	// commits a replacement from it to prove both reads observe one snapshot.
	// Production leaves it nil.
	AfterEnvReadBeforeSecrets func()

	// BeforeBackupRunCommit is a nil-by-default test seam invoked inside
	// CreateBackupWithTarget after the target row's shared lock is held and
	// before the run is inserted. A test blocks it to hold a run open and
	// prove a concurrent destination edit serializes behind the run.
	// Production leaves it nil.
	BeforeBackupRunCommit func()
}

// New wires a Store to an existing pool.
func New(pool *pgxpool.Pool) *Store {
	return &Store{
		DB:      pool,
		queries: sqlc.New(pool),
	}
}

